// 当前100/500真实边界的A域窄门：用中央唯一receipt codec和C真实名册适配器，不执行世界推进。
#include "resident/kernel/world_codec.hpp"
#include "resident/domains/military/military_codec.hpp"
#include "resident/domains/interaction/interaction_access.hpp"
#include <fstream>
#include <iostream>
#ifdef NDEBUG
#undef NDEBUG
#endif
#include <cassert>
using namespace hanmo::resident;
namespace {
// 输入直接读已冻结oracle字节，不改种子、删回执或重排字典。
BoundaryValue read(const char* path){std::ifstream file(path);assert(file);auto parsed=parse_boundary_json(std::string((std::istreambuf_iterator<char>(file)),{}));if(!parsed.ok){std::cerr<<path<<":"<<parsed.error.original.code<<"\n";std::abort();}return std::move(parsed.value);}
void exact(const BoundaryValue& expected,const BoundaryValue& actual,const StableId& context){auto compared=compare_boundary(expected,actual);if(!compared.exact()){auto failure=compared.value_difference?*compared.value_difference:*compared.order_difference;std::cerr<<context<<":"<<failure.path<<":"<<failure.reason<<"\n";std::abort();}}
void require(Status status,const StableId& context){if(!status.ok){std::cerr<<context<<":"<<status.error.original.code<<":"<<status.error.original.path<<"\n";std::abort();}}
// 这里仅合成A拥有的记录；完整B/C action/fact payload不属于本测试，不冒充全世界导出。
void check_common_export(const CommonState& state,const BoundaryValue& source,const ResidentResultCodec& receipts){auto output=encode_common_state(state,&receipts);for(const auto& row:boundary::object(output,"common")){if(row.first=="actions"||row.first=="facts")continue;auto* original=source.find(row.first);assert(original);exact(*original,row.second,row.first);}for(const auto& row:state.actions.rows()){auto* saved=state.action_field_order.find(row.first);assert(saved&&*saved==capture_field_order(*source.find("actions")->find(row.first)).value);}for(const auto& row:state.facts.rows())assert(row.second.field_order==capture_field_order(*source.find("facts")->find(row.first)).value);}
// 军团公共资产仍从共同钱包/库存读；容量、重量、余额、预留与owner均取实际边界作独立预期。
std::size_t check_armies(CommonStore& common,const MilitaryState& military,const BoundaryValue& source,const BoundaryValue& data){std::size_t people=0;for(const auto& army:military.armies){if(army.status!="active")continue;const auto* expected=source.find("armies")->find(army.id);assert(expected);assert(army.member_actor_ids==boundary::strings(*expected->find("member_actor_ids"),army.id));const auto* wallet=common.wallet(army.wallet_id);const auto* inventory=common.inventory(army.inventory_id);assert(wallet&&inventory);Owner public_owner{Owner::Kind::organization,army.organization_id,{}};assert(owner_equal(wallet->owner,public_owner)&&owner_equal(inventory->owner,public_owner));auto* raw_wallet=source.find("wallets")->find(army.wallet_id);auto* raw_inventory=source.find("inventories")->find(army.inventory_id);Integer spend=boundary::get_int(*raw_wallet,"balance",army.id);for(const auto& reservation:boundary::object(*raw_wallet->find("reserved"),army.id))spend-=boundary::integer(reservation.second,army.id);auto available=common.spendable(army.wallet_id);assert(available.ok&&available.value==spend);Integer weight=0;for(const auto& lot:boundary::array(*raw_inventory->find("lots"),army.id)){auto item=boundary::get_string(lot,"item_id",army.id);weight+=boundary::get_int(lot,"quantity",army.id)*boundary::get_int(*data.find("items")->find(item),"weight",item);}auto carried=common.inventory_weight(army.inventory_id);assert(carried.ok&&carried.value==weight);
 for(const auto& actor:army.member_actor_ids){auto* group=common.members(actor);assert(group&&*group==army.member_actor_ids);auto location=common.resolved_location(actor);assert(location.ok);const auto* actor_location=source.find("actors")->find(actor)->find("location");auto kind=boundary::get_string(*actor_location,"kind",actor);const auto* expected_location=kind=="InArmy"?source.find("actors")->find(army.commander_actor_id)->find("location"):actor_location;assert(compare_boundary(*expected_location,boundary::encode_location(location.value)).values_equal);++people;}
 for(const auto& prisoner:army.prisoner_ids){auto* group=common.members(prisoner);assert(group&&std::find(group->begin(),group->end(),army.commander_actor_id)==group->end());}
 }return people;}
}
int main(int argc,char** argv){assert(argc>=4);const Integer expected_actors=std::stoll(argv[2]);auto catalog_source=read(argv[1]);const auto& data=*catalog_source.find("data");auto catalog=decode_common_catalog(data);assert(catalog.ok);auto common_catalog=std::make_shared<const CommonCatalog>(std::move(catalog.value));auto estate_catalog=decode_estate_catalog(data,*common_catalog);assert(estate_catalog.ok);ResidentResultCodec receipts;std::size_t receipt_count=0,member_checks=0,maximum_armies=0;
 for(int index=3;index<argc;++index){auto source=read(argv[index]);auto initial=decode_common_seed(source,*common_catalog,&receipts);auto military=decode_military_seed(source);auto social=decode_social_seed(source);auto estate=decode_estate_seed(source);if(!initial.ok||!military.ok||!social.ok||!estate.ok){std::cerr<<argv[index]<<":"<<(!initial.ok?initial.error.original.code:!military.ok?military.error.original.code:!social.ok?social.error.original.code:estate.error.original.code)<<"\n";return 1;}CommonStore common(std::move(initial.value),common_catalog);MilitaryMembership binding(military.value);common.bind_membership(&binding);assert(common.actor_order().size()==static_cast<std::size_t>(expected_actors));require(common.validate_common(),"common");require(validate_social(common,social.value,*common_catalog),"social");require(validate_estate(common,estate.value,estate_catalog.value,*common_catalog),"estate");check_common_export(common.state(),source,receipts);member_checks+=check_armies(common,military.value,source,data);maximum_armies=std::max(maximum_armies,military.value.armies.size());
 // 所有原缓存都保留并通过中央完整明细codec核对；合法空details不等于null回执。
 for(const auto& row:common.state().results.rows()){assert(row.second&&row.second->ok);exact(*source.find("results")->find(row.first),receipts.encode(*row.second),"receipt/"+row.first);++receipt_count;}
 CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);require(visit_common_checkpoint(writer,common.state(),&receipts),"common.write");require(writer.finish(),"common.write.finish");CommonState restored_state;const auto& input=bytes;CodecVisitor reader(input);require(visit_common_checkpoint(reader,restored_state,&receipts),"common.read");require(reader.finish(),"common.read.finish");CommonStore restored(std::move(restored_state),common_catalog);auto military_copy=military.value;MilitaryMembership restored_binding(military_copy);restored.bind_membership(&restored_binding);require(restored.validate_common(),"common.restored");check_common_export(restored.state(),source,receipts);member_checks+=check_armies(restored,military_copy,source,data);CodecVisitor::Buffer repeated;CodecVisitor rewriter(repeated);require(visit_common_checkpoint(rewriter,restored.state(),&receipts),"common.rewrite");require(rewriter.finish(),"common.rewrite.finish");assert(repeated==bytes);
 auto social_output=encode_social_state(social.value);for(const auto& row:boundary::object(social_output,"social"))exact(*source.find(row.first),row.second,row.first);auto estate_output=encode_estate_state(estate.value);exact(*source.find("estates"),*estate_output.find("estates"),"estates");for(const auto& row:boundary::object(*estate_output.find("facts"),"facts"))exact(*source.find("facts")->find(row.first),row.second,row.first);
 CodecVisitor::Buffer social_bytes;CodecVisitor sw(social_bytes);require(visit_social_checkpoint(sw,social.value),"social.write");require(sw.finish(),"social.write.finish");SocialState social_copy;const auto& si=social_bytes;CodecVisitor sr(si);require(visit_social_checkpoint(sr,social_copy),"social.read");require(sr.finish(),"social.read.finish");exact(social_output,encode_social_state(social_copy),"social.checkpoint");require(validate_social(restored,social_copy,*common_catalog),"social.restored");
 CodecVisitor::Buffer estate_bytes;CodecVisitor ew(estate_bytes);require(visit_estate_checkpoint(ew,estate.value),"estate.write");require(ew.finish(),"estate.write.finish");EstateState estate_copy;const auto& ei=estate_bytes;CodecVisitor er(ei);require(visit_estate_checkpoint(er,estate_copy),"estate.read");require(er.finish(),"estate.read.finish");exact(estate_output,encode_estate_state(estate_copy),"estate.checkpoint");require(validate_estate(restored,estate_copy,estate_catalog.value,*common_catalog),"estate.restored");
 }
 if(expected_actors==100)assert(maximum_armies==2&&member_checks>0);std::cout<<"state_scale_boundaries: PASS actors="<<expected_actors<<" boundaries="<<(argc-3)<<" cached_receipts="<<receipt_count<<" army_member_queries="<<member_checks<<" maximum_armies="<<maximum_armies<<" (A values/order/checkpoint, real C membership/assets, central receipt codec; no advance run)\n";
}
